    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Mark cells belonging to monochromatic rectangles, including singleton-width shapes.
    # All colored objects in this task are solid rectangles; markers are noise removed.
    for color in set(v for row in grid for v in row)-{9}:
        cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if not cells: continue
        # Keep the largest axis-aligned solid rectangle for each color component.
        seen=set()
        for sr,sc in cells:
            if (sr,sc) in seen: continue
            stack=[(sr,sc)]; comp=[]; seen.add((sr,sc))
            while stack:
                r,c=stack.pop(); comp.append((r,c))
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    a,b=q
                    if 0<=a<h and 0<=b<w and grid[a][b]==color and q not in seen: seen.add(q); stack.append(q)
            minr=min(r for r,c in comp); maxr=max(r for r,c in comp); minc=min(c for r,c in comp); maxc=max(c for r,c in comp)
            for r,c in comp:
                if len(comp)>=4: continue
                out[r][c]=9
        # In this puzzle color 9 is the background and each colored rectangle is intact;
        # discard non-rectangular small colored components (noise).
        for r,c in cells:
            if grid[r][c]==color and sum(1 for rr,cc in cells if rr==r and cc==c)==0: out[r][c]=9
    # Remove every non-9 pixel not part of a rectangle with area >= 4 and fully filled.
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==9: continue
            # find maximal 4-neighbor component
            seen=set(); stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and grid[x][y]==col and (x,y) not in seen: seen.add((x,y)); stack.append((x,y))
            rs=[x for x,y in comp]; cs=[y for x,y in comp]
            area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
            if len(comp)<4 or area!=len(comp): out[r][c]=9
    return out

